import os
import json
import queue
import threading
import time
import hashlib
from datetime import datetime
from flask import Flask, request, Response, jsonify
from flask_cors import CORS
from dotenv import load_dotenv
from exa_py import Exa
from openai import OpenAI
import requests

load_dotenv()

app = Flask(__name__)
CORS(app)
app.config['SECRET_KEY'] = os.getenv('FLASK_SECRET_KEY', 'dev-secret-key-change-in-production')

exa_client = Exa(api_key=os.getenv('EXA_API_KEY'))
xai_client = OpenAI(api_key=os.getenv('XAI_API_KEY'), base_url='https://api.x.ai/v1')
cerebras_client = OpenAI(api_key=os.getenv('CEREBRAS_API_KEY'), base_url='https://api.cerebras.ai/v1')
modal_endpoint_url = os.getenv('MODAL_ENDPOINT_URL', '')

streams = {}
research_state = {}

class ResearchOrchestrator:
    def __init__(self, query, job_id):
        self.query = query
        self.job_id = job_id
        self.evidence_chain = []
        self.visited_sources = set()
        self.iteration = 0
        self.max_iterations = 15

    def stream_update(self, event_type, content, metadata=None):
        if self.job_id in streams:
            update = {
                'event': event_type,
                'content': content,
                'timestamp': datetime.now().isoformat(),
                'iteration': self.iteration,
                'metadata': metadata or {}
            }
            streams[self.job_id].put(update)

    def plan_investigation(self, context):
        self.stream_update('planning', 'Gondolkodási fázis: kutatási terv készítése...')

        prompt = f'''Elemezd a következő kutatási kérdést és készíts strukturált tervet.

Kérdés: {self.query}

Eddigi kontextus:
{json.dumps(context, indent=2, ensure_ascii=False)}

Add meg JSON formátumban:
{{
  "investigation_steps": ["első lépés", "második lépés"],
  "search_queries": ["keresési lekérdezés 1", "keresési lekérdezés 2"],
  "reasoning": "miért ezek a lépések fontosak",
  "priority": "high/medium/low"
}}'''

        try:
            response = xai_client.chat.completions.create(
                model='grok-4-fast-reasoning',
                messages=[
                    {'role': 'system', 'content': 'Te egy haladó nyomozati elemző vagy. Strukturált JSON választ adj vissza.'},
                    {'role': 'user', 'content': prompt}
                ],
                response_format={'type': 'json_object'},
                temperature=0.3
            )

            plan = json.loads(response.choices[0].message.content)
            self.stream_update('plan_complete', 'Terv elkészült', plan)
            return plan
        except Exception as e:
            self.stream_update('error', f'Terv készítés hiba: {str(e)}')
            return {'investigation_steps': [self.query], 'search_queries': [self.query], 'reasoning': 'Fallback keresés', 'priority': 'medium'}

    def execute_search(self, search_queries):
        self.stream_update('searching', f'Keresés indítása {len(search_queries)} lekérdezéssel...')

        all_results = []
        for query in search_queries[:3]:
            try:
                self.stream_update('search_query', f'Keresés: {query}')

                result = exa_client.search_and_contents(
                    query=query,
                    type='auto',
                    num_results=10,
                    text={'max_characters': 3000},
                    highlights={'num_sentences': 5, 'highlights_per_url': 3},
                    livecrawl='preferred',
                    use_autoprompt=True
                )

                for item in result.results:
                    if item.url not in self.visited_sources:
                        all_results.append({
                            'url': item.url,
                            'title': item.title or '',
                            'text': item.text or '',
                            'highlights': item.highlights or [],
                            'published_date': item.published_date or '',
                            'author': item.author or '',
                            'query': query
                        })
                        self.visited_sources.add(item.url)

                self.stream_update('search_results', f'{len(result.results)} találat: {query}', {
                    'query': query,
                    'count': len(result.results)
                })

                time.sleep(0.5)
            except Exception as e:
                self.stream_update('search_error', f'Keresési hiba: {str(e)}')

        return all_results

    def analyze_and_infer(self, search_results, context):
        self.stream_update('analyzing', f'{len(search_results)} forrás elemzése és következtetések levonása...')

        results_summary = []
        for idx, result in enumerate(search_results[:10]):
            results_summary.append({
                'index': idx,
                'url': result['url'],
                'title': result['title'],
                'highlights': result['highlights'],
                'text_preview': result['text'][:500]
            })

        prompt = f'''Eredeti kutatási kérdés: {self.query}

Eddigi bizonyítékok és nyomok:
{json.dumps(self.evidence_chain[-3:], indent=2, ensure_ascii=False)}

Új találatok:
{json.dumps(results_summary, indent=2, ensure_ascii=False)}

Feladat:
1. Elemezd az új információkat
2. Kapcsold össze a korábbi bizonyítékokkal
3. Vonj le következtetéseket
4. Azonosítsd az új nyomokat amit tovább kell követni

JSON válasz:
{{
  "key_findings": ["új felfedezés 1", "új felfedezés 2"],
  "connections": ["kapcsolat 1 korábbi bizonyítékokkal"],
  "new_leads": ["új nyom 1 helyszín/személy/esemény", "új nyom 2"],
  "confidence": "high/medium/low",
  "evidence_summary": "összefoglaló",
  "next_investigation_target": "konkrét következő cél"
}}'''

        try:
            response = xai_client.chat.completions.create(
                model='grok-4-fast-reasoning',
                messages=[
                    {'role': 'system', 'content': 'Te egy professzionális nyomozó vagy. Következtess, elemezz és találj összefüggéseket. JSON választ adj.'},
                    {'role': 'user', 'content': prompt}
                ],
                response_format={'type': 'json_object'},
                temperature=0.4
            )

            analysis = json.loads(response.choices[0].message.content)

            self.evidence_chain.append({
                'iteration': self.iteration,
                'findings': analysis['key_findings'],
                'connections': analysis['connections'],
                'sources': [r['url'] for r in search_results[:5]],
                'timestamp': datetime.now().isoformat()
            })

            self.stream_update('analysis_complete', 'Elemzés kész', analysis)
            return analysis
        except Exception as e:
            self.stream_update('error', f'Elemzési hiba: {str(e)}')
            return {'key_findings': [], 'new_leads': [], 'confidence': 'low', 'evidence_summary': 'Hiba történt'}

    def deep_dive_source(self, url, context_question):
        self.stream_update('deep_dive', f'Mély elemzés: {url}')

        try:
            result = exa_client.get_contents(
                ids=[url],
                text={'max_characters': 5000},
                highlights={'num_sentences': 8, 'highlights_per_url': 5},
                livecrawl='always'
            )

            if result.results:
                content = result.results[0]

                prompt = f'''Kérdés kontextus: {context_question}

Teljes forrás tartalma:
URL: {content.url}
Cím: {content.title}
Szöveg:
{content.text or ''}

Elemezd részletesen ezt a forrást és találd meg a rejtett információkat amit mások nem vennének észre.'''

                response = cerebras_client.chat.completions.create(
                    model='gpt-oss-120b',
                    messages=[
                        {'role': 'system', 'content': 'Te egy részletekre fókuszáló elemző vagy.'},
                        {'role': 'user', 'content': prompt}
                    ],
                    temperature=0.3,
                    max_tokens=2000
                )

                insights = response.choices[0].message.content
                self.stream_update('deep_dive_complete', f'Mély elemzés befejezve', {
                    'url': url,
                    'insights': insights
                })
                return insights
        except Exception as e:
            self.stream_update('error', f'Mély elemzés hiba: {str(e)}')
            return None

    def run_investigation_loop(self):
        context = {'query': self.query, 'started': datetime.now().isoformat()}

        self.stream_update('start', f'Kutatás indítása: {self.query}')

        while self.iteration < self.max_iterations:
            self.iteration += 1
            self.stream_update('iteration', f'Iteráció {self.iteration}/{self.max_iterations}')

            plan = self.plan_investigation(context)

            search_results = self.execute_search(plan['search_queries'])

            if not search_results:
                self.stream_update('warning', 'Nincs új találat, következő iteráció...')
                continue

            analysis = self.analyze_and_infer(search_results, context)

            if analysis['new_leads'] and len(analysis['new_leads']) > 0:
                top_lead = analysis['new_leads'][0]
                self.stream_update('new_lead', f'Új nyom követése: {top_lead}')

                context['last_lead'] = top_lead
                context['last_findings'] = analysis['key_findings']

                if len(search_results) > 0:
                    top_source = search_results[0]['url']
                    self.deep_dive_source(top_source, top_lead)

            if analysis['confidence'] == 'high' and len(self.evidence_chain) >= 5:
                self.stream_update('progress', 'Elég bizonyíték gyűlt össze, utolsó ellenőrzés...')
                break

            time.sleep(1)

        self.generate_final_report()

    def generate_final_report(self):
        self.stream_update('generating_report', 'Végső jelentés összeállítása...')

        prompt = f'''Kutatási kérdés: {self.query}

Összegyűjtött bizonyítékok ({len(self.evidence_chain)} iteráció):
{json.dumps(self.evidence_chain, indent=2, ensure_ascii=False)}

Látogatott források ({len(self.visited_sources)}):
{list(self.visited_sources)[:20]}

Készíts részletes, professzionális jelentést amit egy nyomozó írna. Foglald össze:
1. Mit találtunk
2. Hogyan kapcsolódnak a bizonyítékok
3. Milyen új információkat fedeztünk fel
4. Milyen következtetéseket vonhatunk le
5. Mi az amit senki más nem találna meg egyszerű googglezéssel

Írd emberi nyelven, szakmai stílusban.'''

        try:
            response = xai_client.chat.completions.create(
                model='grok-4-fast-reasoning',
                messages=[
                    {'role': 'system', 'content': 'Te egy professzionális nyomozó vagy aki részletes jelentéseket ír.'},
                    {'role': 'user', 'content': prompt}
                ],
                temperature=0.5,
                max_tokens=4000
            )

            report = response.choices[0].message.content

            self.stream_update('report', report, {
                'total_iterations': self.iteration,
                'sources_visited': len(self.visited_sources),
                'evidence_pieces': len(self.evidence_chain)
            })
        except Exception as e:
            self.stream_update('error', f'Jelentés generálási hiba: {str(e)}')

        self.stream_update('complete', 'Kutatás befejezve')

def start_research_job(query, job_id):
    orchestrator = ResearchOrchestrator(query, job_id)
    orchestrator.run_investigation_loop()

@app.route('/api/ask', methods=['POST'])
def ask():
    try:
        data = request.get_json(force=True)
        query = data.get('query', '').strip()

        if not query:
            return jsonify({'error': 'Hiányzó query paraméter'}), 400

        if len(query) > 2000:
            return jsonify({'error': 'Query túl hosszú (max 2000 karakter)'}), 400

        job_id = hashlib.md5(f'{query}{time.time()}{os.urandom(8)}'.encode()).hexdigest()
        streams[job_id] = queue.Queue()
        research_state[job_id] = {'status': 'running', 'started': datetime.now().isoformat()}

        thread = threading.Thread(target=start_research_job, args=(query, job_id), daemon=True)
        thread.start()

        return jsonify({
            'job_id': job_id,
            'status': 'started',
            'message': 'Kutatás elindítva'
        })
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/api/stream', methods=['GET'])
def stream():
    job_id = request.args.get('job_id')

    if not job_id:
        return jsonify({'error': 'Hiányzó job_id paraméter'}), 400

    if job_id not in streams:
        return jsonify({'error': 'Ismeretlen job_id'}), 404

    def generate():
        q = streams[job_id]
        try:
            while True:
                try:
                    item = q.get(timeout=120)
                    yield f'data: {json.dumps(item, ensure_ascii=False)}\n\n'

                    if item.get('event') in ['complete', 'error']:
                        break
                except queue.Empty:
                    yield f'data: {json.dumps({"event": "heartbeat", "timestamp": datetime.now().isoformat()}, ensure_ascii=False)}\n\n'
        finally:
            if job_id in streams:
                del streams[job_id]
            if job_id in research_state:
                research_state[job_id]['status'] = 'completed'

    return Response(generate(), mimetype='text/event-stream', headers={
        'Cache-Control': 'no-cache',
        'X-Accel-Buffering': 'no'
    })

@app.route('/api/status/<job_id>', methods=['GET'])
def status(job_id):
    if job_id in research_state:
        return jsonify(research_state[job_id])
    return jsonify({'error': 'Job nem található'}), 404

@app.route('/api/health', methods=['GET'])
def health():
    return jsonify({
        'status': 'healthy',
        'timestamp': datetime.now().isoformat(),
        'active_jobs': len(streams)
    })

@app.route('/')
def index():
    return app.send_static_file('index.html')

if __name__ == '__main__':
    if not os.getenv('EXA_API_KEY'):
        print('WARNING: EXA_API_KEY not set')
    if not os.getenv('XAI_API_KEY'):
        print('WARNING: XAI_API_KEY not set')
    if not os.getenv('CEREBRAS_API_KEY'):
        print('WARNING: CEREBRAS_API_KEY not set')

    port = int(os.getenv('PORT', 5000))
    app.run(host='0.0.0.0', port=port, debug=False, threaded=True)



